{"projectName":"express-rest-api-prod","description":"A production-ready Node.js REST API built with ES6 modules (import/export) using Express.js, running on Node.js 20+. Uses an in-memory data store (no database), Jest for testing with 80%+ coverage, ESLint + Prettier for code quality, and npm as the package manager. Adheres to RESTful best practices, modern tooling, and deployment readiness with containerized packaging (Docker).","language":"javascript","moduleSystem":"esm","runtime":"node","nodeVersion":"20.0.0","framework":"express","packageManager":"npm","codingStandards":{"eslintConfig":"airbnb-base","prettier":true,"styleGuide":"airbnb","strictMode":false},"testing":{"framework":"jest","coverageRequired":true,"coverageThreshold":80},"buildTool":"esbuild","envConstraints":{"PORT":"3000","NODE_ENV":"development"},"deployment":{"platform":"docker","containerized":true},"response":"ProjectContract for a production-ready Express-based REST API. BoxSpecs are defined to ensure clear separation of concerns, minimal coupling, and test-first design. Core boxes: InMemoryStore (CRUD), ApiRouter (express.Router wiring), Controllers (resource handlers), Validation (input shapes), ErrorHandling (standardized errors), Logging (request/response logs), HealthCheck, Tests (Jest suite with 80%+ coverage), and Deployment artifacts (Dockerfile, npm scripts, CI). Input/Output schemas for key boxes are defined in-line in the acceptance tests and API surface. Acceptance tests cover health endpoint, CRUD on a sample resource, validation errors, error paths, and lifecycle of in-memory data. CI/CD pipeline uses GitHub Actions to enforce lint/format, run Jest tests with coverage, and build Docker image for deployment.","code":"/* index.js */
import express from 'express';
import helmet from 'helmet';
import { createStore } from './store.js';
import apiRouter from './routes/api.js';

const app = express();
const PORT = process.env.PORT || 3000;

app.use(helmet());
app.use(express.json());

const store = createStore();

app.use('/api', apiRouter(store));

app.get('/health', (req, res) => res.json({ status: 'ok', timestamp: Date.now() }));

// Global error handler
app.use((err, req, res, next) => {
  const status = err?.status || 500;
  res.status(status).json({ error: err.message || 'Internal Server Error' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/* src/store.js */
export function createStore() {
  const items = new Map();
  let idCounter = 1;
  return {
    list() { return Array.from(items.values()); },
    get(id) { return items.get(id); },
    create(data) {
      const id = String(idCounter++);
      const entity = { id, ...data };
      items.set(id, entity);
      return entity;
    },
    update(id, data) {
      if (!items.has(id)) throw new Error('Not Found');
      const updated = { ...items.get(id), ...data };
      items.set(id, updated);
      return updated;
    },
    delete(id) {
      if (!items.has(id)) throw new Error('Not Found');
      items.delete(id);
      return true;
    }
  };
}

/* src/routes/api.js */
import express from 'express';
export default function buildApiRouter(store) {
  const router = express.Router();
  router.get('/items', (req, res) => res.json(store.list()));
  router.post('/items', (req, res) => {
    const item = store.create(req.body);
    res.status(201).json(item);
  });
  router.get('/items/:id', (req, res) => {
    const item = store.get(req.params.id);
    if (!item) return res.status(404).json({ error: 'Not Found' });
    res.json(item);
  });
  router.put('/items/:id', (req, res) => {
    try {
      const updated = store.update(req.params.id, req.body);
      res.json(updated);
    } catch (e) {
      res.status(404).json({ error: e.message });
    }
  });
  router.delete('/items/:id', (req, res) => {
    try {
      store.delete(req.params.id);
      res.status(204).end();
    } catch (e) {
      res.status(404).json({ error: e.message });
    }
  });
  return router;
}
